#include "gui/ui/screens/inspector/InspectorController.h"
#include <cstdlib>
#include <iostream>
using namespace ingnomia::ui; using namespace ingnomia::ui::inspector;
namespace{void check(bool v,const char*m){if(!v){std::cerr<<m<<'\n';std::exit(1);}}struct Port:InspectorCommandPort{std::vector<UiActionEnvelope> actions;CommandResult dispatch(const UiActionEnvelope&a)override{actions.push_back(a);return{};}};struct View:InspectorViewPort{InspectorState state;int changes{};void stateChanged(const InspectorState&s)override{state=s;++changes;}};}
int main(){Port p;View v;InspectorController c(p,v);c.beginWorld(WorldEpoch{73});TileInspectorState tile;tile.id=TileId{1204};tile.position={4,5,6};tile.wall="Granite wall";tile.canMine=true;tile.canManage=true;tile.designation=DesignationId{91};tile.designationName="Forge";tile.creatures.push_back({CreatureId{22},"Gnome: Ada",EntityKind::Creature});c.showTile(tile);check(c.state().kind==InspectorKind::Tile&&c.state().selected->world.value==73&&c.state().selected->id==1204,"typed tile selection");c.executeContext(TileContextAction::Mine);check(p.actions.back().id.value=="tile.execute_context_action"&&std::get<TileContextPayload>(p.actions.back().payload).tile.value==1204,"typed context action");c.openCreature(CreatureId{22});check(std::get<SelectPayload>(p.actions.back().payload).target.id==22,"stable creature target");CreatureInspectorState creature;creature.id=CreatureId{22};creature.name="Ada";creature.equipmentRole=MilitaryRoleId{71};creature.equipmentRoleName="Guard";creature.equipmentSlots.push_back({UniformSlot::HeadArmor,"Head","ChainArmorHead","iron","../tilesheet/inventory_ChainArmorHead.tga",CatalogId{"Chainmail"},CatalogId{"iron"},{{CatalogId{"none"},{CatalogId{"any"}}},{CatalogId{"Chainmail"},{CatalogId{"any"},CatalogId{"iron"}}}}});c.showCreature(creature,WorldPosition{4,5,6});c.selectEquipmentSlot(UniformSlot::HeadArmor);check(c.state().equipmentSlotEditor==UniformSlot::HeadArmor&&c.state().equipmentDraftType.value=="Chainmail","equipment slot opens authoritative draft");c.setEquipmentDraftType(CatalogId{"none"});c.applyEquipmentSlot();check(p.actions.size()>=2&&p.actions[p.actions.size()-2].id.value=="military.set_uniform_slot","equipment mutation uses typed uniform action");const auto& equipmentPayload=std::get<SetUniformSlotPayload>(p.actions[p.actions.size()-2].payload);check(equipmentPayload.role.value==71&&equipmentPayload.slot==UniformSlot::HeadArmor&&equipmentPayload.type.value=="none","equipment mutation preserves role and slot");c.setProfessionChoices({"Miner","Builder"});check(c.state().professionChoices.size()==2,"profession choices project");c.setProfession("Miner");check(p.actions.back().id.value=="population.set_profession"&&std::get<SetProfessionPayload>(p.actions.back().payload).creature.value==22&&std::get<SetProfessionPayload>(p.actions.back().payload).profession.value=="Miner","profession mutation route");check(c.state().previous->id==1204&&c.state().kind==InspectorKind::Creature,"target route change retains previous");c.back();check(p.actions.back().id.value=="inspect.select"&&std::get<SelectPayload>(p.actions.back().payload).target.id==1204,"back requests previous target");
WorkshopInspectorState ws;ws.id=WorkshopId{10};ws.name="Forge";ws.suspended=false;c.showWorkshop(ws);c.toggleWorkshopSuspended();check(p.actions.back().id.value=="workshop.set_basics"&&std::get<SetWorkshopBasicsPayload>(p.actions.back().payload).suspended,"workshop representative mutation");StockpileInspectorState sp;sp.id=StockpileId{11};sp.name="Stone";c.showStockpile(sp);c.toggleStockpileSuspended();check(p.actions.back().id.value=="stockpile.set_basics"&&std::get<SetStockpileBasicsPayload>(p.actions.back().payload).suspended,"stockpile representative mutation");AgricultureInspectorState ag;ag.target={AgricultureKind::Farm,DesignationId{12}};ag.name="Mushrooms";ag.harvest=true;c.showAgriculture(ag);c.toggleAgricultureSuspended();check(p.actions.back().id.value=="agriculture.set_basics","agri suspend mutation");c.toggleAgriculturePrimaryOption();check(p.actions.back().id.value=="agriculture.set_harvest_options"&&!std::get<SetHarvestOptionsPayload>(p.actions.back().payload).harvest,"agri option mutation");c.locate();check(p.actions.back().id.value=="view.center_on","locate action");c.setSelectionAction("BuildWorkshop",true);c.rotateSelection();check(p.actions.back().id.value=="tool.rotate","selection rotate");c.cancelSelection();check(p.actions.back().id.value=="tool.cancel","selection cancel");c.close();check(c.state().kind==InspectorKind::None&&p.actions.back().id.value=="inspect.clear","close clears inspector");c.endWorld();const auto n=p.actions.size();c.showTile(tile);c.cancelSelection();check(c.state().kind==InspectorKind::None&&p.actions.size()==n,"unload blocks late state and actions");check(!c.state().world&& !c.state().selected,"unload clears epoch and target");std::cout<<"Inspector controller target/mutation/lifecycle tests passed\n";}
